                      transition={{ delay: 0.3 }}
                    >
                      KEN TAYLOR
                    </motion.h3>

                    <motion.p 
                      className="text-accent font-mono text-sm mb-6 tracking-wider"
                      initial={{ opacity: 0, x: -20 }}
                      whileInView={{ opacity: 1, x: 0 }}
                      viewport={{ once: true }}
                      transition={{ delay: 0.4 }}
                    >
