interface Props {
  title?: string;
  description?: string;
  canonical?: string;
  image?: {
    src: string;
    alt?: string;
    width?: number;
    height?: number;
    type?: string;
  };
  keywords?: string[];
  robots?: string;
  type?: 'website' | 'article';
  publishedTime?: string;
  modifiedTime?: string;
  articleTags?: string[];
  authorUrl?: string;
  jsonLd?: JsonLd | JsonLd[];
}

const {
  title = SITE.defaultTitle,
  description = SITE.defaultDescription,
  canonical,
  image,
  keywords = [],
  robots,
